130	impl InterpreterRef<'_> {
131	    fn vm_state(&mut self) -> &mut VmState {
132	        // SAFETY: This is a bit of a tricky code. The safety here is isolated
133	        // to this file, but not isolated to just this function call.
134	        //
135	        // An `InterpreterRef` guarantees that we have a pointer to a `Vm`, and
136	        // that pointer originates from a `StoreBox<VM>` in the store itself.
137	        // One level of safety here relies on that never being deallocated or
138	        // overwritten, which this file upholds as it's a private field only
